'use strict';

class RuntimeError extends Error {
  constructor(position, message) { super(message); this.position = position; }
}

function closure(expression, environment) {
  return {kind: 'closure', parameter: expression.parameter, body: expression.body, environment};
}

function builtin(name, apply) { return {kind: 'builtin', name, apply}; }

function integer(value, position) {
  if (value < -2147483648n || value > 2147483647n) throw new RuntimeError(position, 'integer overflow');
  return Number(value);
}

function compare(first, second, position) {
  const pending = [[first, second]];
  while (pending.length > 0) {
    const [left, right] = pending.pop();
    if (typeof left !== 'object') {
      if (left < right) return -1;
      if (left > right) return 1;
    } else if (Array.isArray(left)) {
      pending.push([left.length, right.length]);
      for (let i = Math.min(left.length, right.length) - 1; i >= 0; i--) pending.push([left[i], right[i]]);
    } else if (left.kind === 'pair') {
      pending.push([left.second, right.second], [left.first, right.first]);
    } else throw new RuntimeError(position, 'functional value compared');
  }
  return 0;
}

function binary(operator, left, right, position) {
  if (operator === '+') return integer(BigInt(left) + BigInt(right), position);
  if (operator === '-') return integer(BigInt(left) - BigInt(right), position);
  if (operator === '*') return integer(BigInt(left) * BigInt(right), position);
  if (operator === '/' || operator === 'mod') {
    if (right === 0) throw new RuntimeError(position, 'division by zero');
    return integer(operator === '/' ? BigInt(left) / BigInt(right) : BigInt(left) % BigInt(right), position);
  }
  if (operator === '^') return left + right;
  if (operator === '::') return [left, ...right];
  if (operator === '&&' || operator === '||') return right;
  const order = compare(left, right, position);
  if (operator === '=') return order === 0;
  if (operator === '<>') return order !== 0;
  if (operator === '<') return order < 0;
  if (operator === '>') return order > 0;
  if (operator === '<=') return order <= 0;
  return order >= 0;
}

function match(pattern, value) {
  const bindings = new Map();
  const pending = [[pattern, value]];
  while (pending.length > 0) {
    const [current, found] = pending.pop();
    switch (current.kind) {
      case 'wildcard': break;
      case 'name': bindings.set(current.name, found); break;
      case 'int': case 'bool': case 'string':
        if (current.value !== found) return null;
        break;
      case 'pair':
        pending.push([current.second, found.second], [current.first, found.first]);
        break;
      case 'cons':
        if (found.length === 0) return null;
        pending.push([current.second, found.slice(1)], [current.first, found[0]]);
        break;
      case 'list':
        if (current.elements.length !== found.length) return null;
        for (let i = found.length - 1; i >= 0; i--) pending.push([current.elements[i], found[i]]);
        break;
    }
  }
  return bindings;
}

function recursiveGroup(group, environment) {
  const scope = new Map(environment);
  for (const binding of group.bindings) scope.set(binding.name, closure(binding.expression, scope));
  return scope;
}

class Evaluator {
  constructor() { this.calls = 0; }

  group(group, environment) {
    if (group.recursive) return recursiveGroup(group, environment);
    const values = group.bindings.map(binding => this.expression(binding.expression, environment));
    const scope = new Map(environment);
    group.bindings.forEach((binding, i) => scope.set(binding.name, values[i]));
    return scope;
  }

  expression(expression, environment) {
    const frames = [];
    let current = expression;
    let scope = environment;
    let evaluating = true;
    let value;
    for (;;) {
      if (evaluating) {
        switch (current.kind) {
          case 'int': case 'bool': case 'string': value = current.value; break;
          case 'name': value = scope.get(current.name); break;
          case 'fun': value = closure(current, scope); break;
          case 'application':
            frames.push({kind: 'applicationFunction', argument: current.argument, environment: scope, position: current.position});
            current = current.fn;
            continue;
          case 'binary':
            frames.push({kind: 'binaryLeft', expression: current, environment: scope});
            current = current.left;
            continue;
          case 'unary':
            frames.push({kind: 'unary', position: current.operatorPosition});
            current = current.expression;
            continue;
          case 'if':
            frames.push({kind: 'if', expression: current, environment: scope});
            current = current.condition;
            continue;
          case 'pair':
            frames.push({kind: 'pairFirst', second: current.second, environment: scope});
            current = current.first;
            continue;
          case 'list':
            if (current.elements.length === 0) { value = []; break; }
            frames.push({kind: 'list', elements: current.elements, values: [], environment: scope});
            current = current.elements[0];
            continue;
          case 'match':
            frames.push({kind: 'match', expression: current, environment: scope});
            current = current.matched;
            continue;
          case 'let':
            if (current.group.recursive) {
              scope = recursiveGroup(current.group, scope);
              current = current.body;
            } else {
              frames.push({kind: 'let', expression: current, values: [], environment: scope});
              current = current.group.bindings[0].expression;
            }
            continue;
        }
        evaluating = false;
      }
      if (frames.length === 0) return value;
      const frame = frames.pop();
      switch (frame.kind) {
        case 'applicationFunction':
          frames.push({kind: 'applicationArgument', fn: value, position: frame.position});
          current = frame.argument;
          scope = frame.environment;
          evaluating = true;
          break;
        case 'applicationArgument':
          this.calls++;
          if (frame.fn.kind === 'builtin') value = frame.fn.apply(value, frame.position);
          else {
            scope = new Map(frame.fn.environment);
            if (frame.fn.parameter.name !== '_') scope.set(frame.fn.parameter.name, value);
            current = frame.fn.body;
            evaluating = true;
          }
          break;
        case 'binaryLeft': {
          const operator = frame.expression.operator;
          if ((operator === '&&' && value === false) || (operator === '||' && value === true)) break;
          frames.push({kind: 'binaryRight', expression: frame.expression, first: value});
          current = frame.expression.right;
          scope = frame.environment;
          evaluating = true;
          break;
        }
        case 'binaryRight':
          value = binary(frame.expression.operator, frame.first, value, frame.expression.operatorPosition);
          break;
        case 'unary': value = integer(-BigInt(value), frame.position); break;
        case 'if':
          current = value ? frame.expression.yes : frame.expression.no;
          scope = frame.environment;
          evaluating = true;
          break;
        case 'pairFirst':
          frames.push({kind: 'pairSecond', first: value});
          current = frame.second;
          scope = frame.environment;
          evaluating = true;
          break;
        case 'pairSecond': value = {kind: 'pair', first: frame.first, second: value}; break;
        case 'list':
          frame.values.push(value);
          if (frame.values.length === frame.elements.length) value = frame.values;
          else {
            frames.push(frame);
            current = frame.elements[frame.values.length];
            scope = frame.environment;
            evaluating = true;
          }
          break;
        case 'match': {
          let selected = null;
          for (const arm of frame.expression.arms) {
            const bindings = match(arm.pattern, value);
            if (bindings !== null) { selected = {arm, bindings}; break; }
          }
          if (selected === null) throw new RuntimeError(frame.expression.position, 'match failure');
          scope = new Map(frame.environment);
          for (const [name, found] of selected.bindings) scope.set(name, found);
          current = selected.arm.expression;
          evaluating = true;
          break;
        }
        case 'let': {
          frame.values.push(value);
          const bindings = frame.expression.group.bindings;
          if (frame.values.length < bindings.length) {
            frames.push(frame);
            current = bindings[frame.values.length].expression;
            scope = frame.environment;
          } else {
            scope = new Map(frame.environment);
            bindings.forEach((binding, i) => scope.set(binding.name, frame.values[i]));
            current = frame.expression.body;
          }
          evaluating = true;
          break;
        }
      }
    }
  }
}

module.exports = {RuntimeError, Evaluator, builtin};

'use strict';

const types = require('./unifier');

class InferenceError extends Error {
  constructor(reason, position, details = {}) {
    super(reason);
    Object.assign(this, {reason, position}, details);
  }
}

function check(expected, found, position) {
  const failure = types.unify(expected, found);
  if (failure !== null) throw new InferenceError('check', position, {expected, found, failure});
}

function operatorType(operator) {
  if (['+', '-', '*', '/', 'mod'].includes(operator)) return [types.integer, types.integer, types.integer];
  if (operator === '^') return [types.string, types.string, types.string];
  if (operator === '&&' || operator === '||') return [types.boolean, types.boolean, types.boolean];
  const variable = types.fresh();
  if (operator === '::') return [variable, types.list(variable), types.list(variable)];
  return [variable, variable, types.boolean];
}

class Inferencer {
  constructor() { this.locals = []; }

  expression(expression, environment) {
    let type;
    switch (expression.kind) {
      case 'int': type = types.integer; break;
      case 'string': type = types.string; break;
      case 'bool': type = types.boolean; break;
      case 'name': {
        const scheme = environment.get(expression.name);
        if (scheme === undefined) throw new InferenceError('unbound', expression.position,
          {name: expression.name, candidates: [...environment.keys()]});
        type = types.instantiate(scheme);
        break;
      }
      case 'fun': {
        const parameter = types.fresh();
        const scope = new Map(environment);
        if (expression.parameter.name !== '_') scope.set(expression.parameter.name, types.monomorphic(parameter));
        type = types.fn(parameter, this.expression(expression.body, scope));
        break;
      }
      case 'application': {
        let callable = types.resolve(this.expression(expression.fn, environment));
        if (callable.kind === 'var') {
          callable.bound = types.fn(types.fresh(), types.fresh());
          callable = callable.bound;
        } else if (callable.kind !== 'function') throw new InferenceError('function', expression.fn.position, {found: callable});
        check(callable.args[0], this.expression(expression.argument, environment), expression.argument.position);
        type = callable.args[1];
        break;
      }
      case 'binary': {
        const [first, second, result] = operatorType(expression.operator);
        check(first, this.expression(expression.left, environment), expression.left.position);
        check(second, this.expression(expression.right, environment), expression.right.position);
        type = result;
        break;
      }
      case 'unary':
        check(types.integer, this.expression(expression.expression, environment), expression.expression.position);
        type = types.integer;
        break;
      case 'if': {
        check(types.boolean, this.expression(expression.condition, environment), expression.condition.position);
        const yes = this.expression(expression.yes, environment);
        const no = this.expression(expression.no, environment);
        check(yes, no, expression.no.position);
        type = yes;
        break;
      }
      case 'pair': {
        const first = this.expression(expression.first, environment);
        const second = this.expression(expression.second, environment);
        type = types.pair(first, second);
        break;
      }
      case 'list': {
        const element = types.fresh();
        for (const value of expression.elements) check(element, this.expression(value, environment), value.position);
        type = types.list(element);
        break;
      }
      case 'match': {
        const matched = this.expression(expression.matched, environment);
        const result = types.fresh();
        for (const arm of expression.arms) {
          const bindings = new Map();
          const pattern = this.pattern(arm.pattern, bindings);
          check(matched, pattern, arm.pattern.position);
          const scope = new Map(environment);
          for (const [name, value] of bindings) scope.set(name, types.monomorphic(value));
          check(result, this.expression(arm.expression, scope), arm.expression.position);
        }
        type = result;
        break;
      }
      case 'let': type = this.expression(expression.body, this.group(expression.group, environment, false)); break;
    }
    expression.type = type;
    return type;
  }

  pattern(pattern, bindings) {
    let type;
    switch (pattern.kind) {
      case 'wildcard': type = types.fresh(); break;
      case 'name':
        if (bindings.has(pattern.name)) throw new InferenceError('patternDuplicate', pattern.position, {name: pattern.name});
        type = types.fresh();
        bindings.set(pattern.name, type);
        break;
      case 'int': type = types.integer; break;
      case 'string': type = types.string; break;
      case 'bool': type = types.boolean; break;
      case 'pair': {
        const first = this.pattern(pattern.first, bindings);
        const second = this.pattern(pattern.second, bindings);
        type = types.pair(first, second);
        break;
      }
      case 'cons': {
        const element = types.fresh();
        check(element, this.pattern(pattern.first, bindings), pattern.first.position);
        const list = types.list(element);
        check(list, this.pattern(pattern.second, bindings), pattern.second.position);
        type = list;
        break;
      }
      case 'list': {
        const element = types.fresh();
        for (const value of pattern.elements) check(element, this.pattern(value, bindings), value.position);
        type = types.list(element);
        break;
      }
    }
    pattern.type = type;
    return type;
  }

  group(group, environment, topLevel) {
    const names = new Set();
    for (const binding of group.bindings) {
      if (names.has(binding.name)) throw new InferenceError('letDuplicate', binding.position, {name: binding.name});
      names.add(binding.name);
      if (group.recursive && binding.expression.kind !== 'fun') throw new InferenceError('recFunction', binding.position, {name: binding.name});
    }
    let inferred;
    if (group.recursive) {
      inferred = group.bindings.map(() => types.fresh());
      const scope = new Map(environment);
      group.bindings.forEach((binding, i) => scope.set(binding.name, types.monomorphic(inferred[i])));
      for (let i = 0; i < group.bindings.length; i++) {
        const binding = group.bindings[i];
        check(inferred[i], this.expression(binding.expression, scope), binding.position);
      }
    } else inferred = group.bindings.map(binding => this.expression(binding.expression, environment));
    const result = new Map(environment);
    for (let i = 0; i < group.bindings.length; i++) {
      const binding = group.bindings[i];
      binding.scheme = types.generalize(inferred[i], environment);
      result.set(binding.name, binding.scheme);
      if (!topLevel) this.locals.push(binding);
    }
    return result;
  }
}

module.exports = {Inferencer, InferenceError, check};

'use strict';

const keywords = new Set(['let', 'rec', 'and', 'in', 'fun', 'if', 'then', 'else', 'match', 'with', 'true', 'false', 'mod', 'val']);
const symbols = [';;', '->', '::', '||', '&&', '<=', '>=', '<>', ':', ';', '=', '<', '>', '+', '-', '*', '/', '^', '(', ')', '[', ']', ',', '|'];

function tokenize(text, file) {
  const tokens = [];
  let index = 0;
  let line = 1;
  let column = 1;
  function advance(length) {
    for (let end = index + length; index < end; index++) {
      if (text[index] === '\n') { line++; column = 1; }
      else column++;
    }
  }
  function token(kind, length, value, message) {
    tokens.push({kind, text: text.slice(index, index + length), value, message, position: {file, line, column}});
    advance(length);
  }
  while (index < text.length) {
    const character = text[index];
    if (character === ' ' || character === '\n') { advance(1); continue; }
    if (text.startsWith('(*', index)) {
      const end = text.indexOf('*)', index + 2);
      if (end === -1) { token('invalid', text.length - index, null, 'unterminated comment'); break; }
      advance(end + 2 - index);
      continue;
    }
    if (/[0-9]/.test(character)) {
      let end = index + 1;
      while (end < text.length && /[0-9]/.test(text[end])) end++;
      const value = Number(text.slice(index, end));
      if (value > 2147483647) token('invalid', end - index, null, 'integer literal too large');
      else token('int', end - index, value);
      continue;
    }
    if (/[A-Za-z_]/.test(character)) {
      let end = index + 1;
      while (end < text.length && /[A-Za-z0-9_']/.test(text[end])) end++;
      const word = text.slice(index, end);
      token(keywords.has(word) ? 'keyword' : 'name', end - index, word);
      continue;
    }
    if (character === "'" && index + 1 < text.length && /[a-z]/.test(text[index + 1])) {
      let end = index + 2;
      while (end < text.length && /[A-Za-z0-9_]/.test(text[end])) end++;
      token('typevar', end - index, text.slice(index, end));
      continue;
    }
    if (character === '"') {
      let end = index + 1;
      let value = '';
      let invalidEscape = false;
      const escapes = {n: '\n', t: '\t', '\\': '\\', '"': '"'};
      while (end < text.length && text[end] !== '"' && text[end] !== '\n') {
        if (text[end] === '\\' && end + 1 < text.length && text[end + 1] !== '\n') {
          const escaped = text[end + 1];
          if (Object.hasOwn(escapes, escaped)) value += escapes[escaped];
          else invalidEscape = true;
          end += 2;
        } else value += text[end++];
      }
      if (end === text.length || text[end] === '\n') token('invalid', end - index, null, 'unterminated string');
      else if (invalidEscape) token('invalid', end + 1 - index, null, 'invalid escape sequence');
      else token('string', end + 1 - index, value);
      continue;
    }
    const symbol = symbols.find(value => text.startsWith(value, index));
    if (symbol !== undefined) token('symbol', symbol.length, symbol);
    else token('invalid', 1, null, `illegal character '${character}'`);
  }
  tokens.push({kind: 'eof', text: '', position: {file, line, column}});
  return tokens;
}

module.exports = {tokenize};

'use strict';

const fs = require('node:fs');
const {tokenize} = require('./lexer');
const {Parser, ParseError, operators} = require('./parser');
const types = require('./unifier');
const {Inferencer, InferenceError} = require('./inference');
const {Evaluator, RuntimeError, builtin} = require('./evaluator');

function positionOrder(first, second) {
  return first.line - second.line || first.column - second.column;
}

function quote(value) {
  const escapes = {'\\': '\\\\', '"': '\\"', '\n': '\\n', '\t': '\\t'};
  return '"' + value.replace(/[\\"\n\t]/g, character => escapes[character]) + '"';
}

function printValue(value) {
  const pieces = [];
  const pending = [{value}];
  while (pending.length > 0) {
    const part = pending.pop();
    if (Object.hasOwn(part, 'text')) { pieces.push(part.text); continue; }
    const current = part.value;
    if (typeof current === 'string') pieces.push(quote(current));
    else if (typeof current !== 'object') pieces.push(String(current));
    else if (Array.isArray(current)) {
      pending.push({text: ']'});
      for (let i = current.length - 1; i >= 0; i--) {
        pending.push({value: current[i]});
        if (i > 0) pending.push({text: '; '});
      }
      pending.push({text: '['});
    } else if (current.kind === 'pair') {
      pending.push({text: ')'}, {value: current.second}, {text: ', '}, {value: current.first}, {text: '('});
    } else pieces.push('<fun>');
  }
  return pieces.join('');
}

function printType(type, names = new Map(), quantified = null) {
  function render(value) {
    value = types.resolve(value);
    if (value.kind === 'variable') return value.name;
    if (value.kind === 'var') {
      if (!names.has(value)) names.set(value, names.size);
      const index = names.get(value);
      const prefix = quantified !== null && !quantified.has(value) ? "'_" : "'";
      return prefix + String.fromCharCode(97 + index % 26) + (index < 26 ? '' : Math.floor(index / 26));
    }
    if (value.args.length === 0) return value.kind;
    const wrap = (component, kinds) => {
      const text = render(component);
      return kinds.includes(types.resolve(component).kind) ? '(' + text + ')' : text;
    };
    if (value.kind === 'list') return wrap(value.args[0], ['pair', 'function']) + ' list';
    if (value.kind === 'pair') return wrap(value.args[0], ['pair', 'function']) + ' * ' + wrap(value.args[1], ['pair', 'function']);
    return wrap(value.args[0], ['function']) + ' -> ' + render(value.args[1]);
  }
  return render(type);
}

function editDistance(first, second) {
  let previous = Array.from({length: second.length + 1}, (_, i) => i);
  for (let i = 0; i < first.length; i++) {
    const current = [i + 1];
    for (let j = 0; j < second.length; j++) {
      current.push(Math.min(current[j] + 1, previous[j + 1] + 1, previous[j] + (first[i] === second[j] ? 0 : 1)));
    }
    previous = current;
  }
  return previous[second.length];
}

function typeErrorMessage(error) {
  const names = new Map();
  const show = type => printType(type, names);
  if (error.reason === 'check') {
    let message = `expected ${show(error.expected)} but found ${show(error.found)}`;
    const failure = error.failure;
    if (failure.kind === 'occurs') message += ` (infinite type ${show(failure.variable)} = ${show(failure.other)})`;
    else if (failure.component) message += ` (${show(failure.expected)} vs ${show(failure.found)})`;
    return message;
  }
  if (error.reason === 'function') return `expected a function but found ${show(error.found)}`;
  if (error.reason === 'patternDuplicate') return `variable '${error.name}' is bound twice in this pattern`;
  if (error.reason === 'letDuplicate') return `variable '${error.name}' is bound twice in this let`;
  if (error.reason === 'recFunction') return `'${error.name}' in let rec must be a function`;
  if (error.reason === 'signature') return `'${error.name}' has type ${show(error.inferred)} but its signature is ${show(error.declared)}`;
  let candidate = null;
  let distance = 3;
  for (const name of error.candidates) {
    const found = editDistance(error.name, name);
    if (found < error.name.length && (found < distance || (found === distance && (candidate === null || name < candidate)))) {
      distance = found;
      candidate = name;
    }
  }
  return `unbound variable '${error.name}'` + (candidate === null || distance > 2 ? '' : ` (did you mean '${candidate}'?)`);
}

function signatureType(expression, variables = new Map()) {
  if (expression.kind === 'variable') {
    if (!variables.has(expression.name)) variables.set(expression.name, types.fresh());
    return variables.get(expression.name);
  }
  return {kind: expression.kind, args: expression.args.map(argument => signatureType(argument, variables))};
}

function equalRigid(first, second) {
  if (first === second) return true;
  if (first.kind !== second.kind || first.kind === 'var') return false;
  return first.args.every((argument, index) => equalRigid(argument, second.args[index]));
}

function acceptsSignature(inferred, declared, assignments = new Map()) {
  inferred = types.resolve(inferred);
  if (inferred.kind === 'var') {
    if (assignments.has(inferred)) return equalRigid(assignments.get(inferred), declared);
    assignments.set(inferred, declared);
    return true;
  }
  return inferred.kind === declared.kind && inferred.args.every((argument, index) => acceptsSignature(argument, declared.args[index], assignments));
}

function checkSignatures(group, signatures, environment) {
  for (let i = 0; i < group.bindings.length; i++) {
    if (signatures[i] === null) continue;
    const binding = group.bindings[i];
    const declared = signatureType(signatures[i].type);
    if (!acceptsSignature(binding.scheme.type, declared)) {
      throw new InferenceError('signature', binding.position,
        {name: binding.name, inferred: binding.scheme.type, declared});
    }
    binding.scheme = {type: declared, quantified: types.freeVariables(declared)};
    environment.set(binding.name, binding.scheme);
  }
}

function initialEnvironments() {
  const typeEnvironment = new Map();
  const valueEnvironment = new Map();
  function add(name, type, apply) {
    typeEnvironment.set(name, {type, quantified: types.freeVariables(type)});
    valueEnvironment.set(name, builtin(name, apply));
  }
  let first = types.fresh();
  let second = types.fresh();
  add('fst', types.fn(types.pair(first, second), first), value => value.first);
  first = types.fresh();
  second = types.fresh();
  add('snd', types.fn(types.pair(first, second), second), value => value.second);
  add('not', types.fn(types.boolean, types.boolean), value => !value);
  add('string_of_int', types.fn(types.integer, types.string), value => String(value));
  add('failwith', types.fn(types.string, types.fresh()), (value, position) => {
    throw new RuntimeError(position, 'failure ' + printValue(value));
  });
  return {typeEnvironment, valueEnvironment};
}

function leadingFunctions(expression) {
  const parameters = [];
  while (expression.kind === 'fun') {
    parameters.push(expression.parameter.name);
    expression = expression.body;
  }
  return {parameters, body: expression};
}

function formatPattern(pattern) {
  if (pattern.kind === 'name') return pattern.name;
  if (pattern.kind === 'wildcard') return '_';
  if (pattern.kind === 'pair') return '(' + formatPattern(pattern.first) + ', ' + formatPattern(pattern.second) + ')';
  if (pattern.kind === 'list') return '[' + pattern.elements.map(formatPattern).join('; ') + ']';
  if (pattern.kind === 'cons') {
    let first = formatPattern(pattern.first);
    if (pattern.first.kind === 'cons') first = '(' + first + ')';
    return first + ' :: ' + formatPattern(pattern.second);
  }
  return printValue(pattern.value);
}

function endsWithMatch(expression) {
  if (expression.kind === 'match') return true;
  if (expression.kind === 'let' || expression.kind === 'fun') return endsWithMatch(expression.body);
  return expression.kind === 'if' && endsWithMatch(expression.no);
}

function formatBinding(binding) {
  const {parameters, body} = leadingFunctions(binding.expression);
  return [binding.name, ...parameters, '=', formatExpression(body)].join(' ');
}

function formatGroup(group) {
  return (group.recursive ? 'let rec ' : 'let ') + group.bindings.map(formatBinding).join(' and ');
}

function formatExpression(expression, required = 0) {
  let text;
  let strength = 9;
  switch (expression.kind) {
    case 'int': case 'bool': case 'string': text = printValue(expression.value); break;
    case 'name': text = expression.name; break;
    case 'fun': {
      const {parameters, body} = leadingFunctions(expression);
      strength = 0;
      text = 'fun ' + parameters.join(' ') + ' -> ' + formatExpression(body);
      break;
    }
    case 'application':
      strength = 8;
      text = formatExpression(expression.fn, 8) + ' ' + formatExpression(expression.argument, 9);
      break;
    case 'binary': {
      const [precedence, rightAssociative] = operators.get(expression.operator);
      strength = precedence;
      text = formatExpression(expression.left, precedence + (rightAssociative ? 1 : 0)) + ' ' + expression.operator + ' ' +
        formatExpression(expression.right, precedence + (rightAssociative ? 0 : 1));
      break;
    }
    case 'unary': strength = 7; text = '-' + formatExpression(expression.expression, 7); break;
    case 'if':
      strength = 0;
      text = 'if ' + formatExpression(expression.condition) + ' then ' + formatExpression(expression.yes) + ' else ' + formatExpression(expression.no);
      break;
    case 'pair': text = '(' + formatExpression(expression.first) + ', ' + formatExpression(expression.second) + ')'; break;
    case 'list': text = '[' + expression.elements.map(value => formatExpression(value)).join('; ') + ']'; break;
    case 'let': strength = 0; text = formatGroup(expression.group) + ' in ' + formatExpression(expression.body); break;
    case 'match':
      strength = 0;
      text = 'match ' + formatExpression(expression.matched) + ' with ' + expression.arms.map((arm, index) => {
        let body = formatExpression(arm.expression);
        if (index + 1 < expression.arms.length && endsWithMatch(arm.expression)) body = '(' + body + ')';
        return formatPattern(arm.pattern) + ' -> ' + body;
      }).join(' | ');
      break;
  }
  return strength < required ? '(' + text + ')' : text;
}

function formatItem(item) {
  if (item.kind === 'signature') return `val ${item.name} : ${printType(item.type)};;`;
  return (item.kind === 'declaration' ? formatGroup(item.group) : formatExpression(item.expression)) + ';;';
}

const wildcard = {tag: '_', args: []};

function patternTree(pattern) {
  if (pattern.kind === 'name' || pattern.kind === 'wildcard') return wildcard;
  if (pattern.kind === 'pair' || pattern.kind === 'cons') {
    return {tag: pattern.kind, args: [patternTree(pattern.first), patternTree(pattern.second)]};
  }
  if (pattern.kind === 'list') {
    let result = {tag: 'nil', args: []};
    for (let i = pattern.elements.length - 1; i >= 0; i--) result = {tag: 'cons', args: [patternTree(pattern.elements[i]), result]};
    return result;
  }
  return {tag: pattern.kind + ':' + String(pattern.value), args: []};
}

function constructors(type) {
  type = types.resolve(type);
  if (type.kind === 'bool') return ['bool:false', 'bool:true'];
  if (type.kind === 'list') return ['nil', 'cons'];
  if (type.kind === 'pair') return ['pair'];
  return null;
}

function constructorArguments(type, tag) {
  type = types.resolve(type);
  if (tag === 'pair') return type.args;
  if (tag === 'cons') return [type.args[0], type];
  return [];
}

function specialize(matrix, tag, arity) {
  const result = [];
  for (const row of matrix) {
    if (row[0].tag === tag) result.push(row[0].args.concat(row.slice(1)));
    else if (row[0].tag === '_') result.push(Array(arity).fill(wildcard).concat(row.slice(1)));
  }
  return result;
}

function useful(matrix, vector, columnTypes) {
  const pending = [{matrix, vector, columnTypes}];
  while (pending.length > 0) {
    const state = pending.pop();
    if (state.matrix.length === 0) return true;
    if (state.vector.length === 0 || state.matrix.some(row => row.every(pattern => pattern.tag === '_'))) continue;
    const [head, ...tail] = state.vector;
    const [type, ...otherTypes] = state.columnTypes;
    if (head.tag !== '_') {
      pending.push({matrix: specialize(state.matrix, head.tag, head.args.length), vector: head.args.concat(tail),
        columnTypes: constructorArguments(type, head.tag).concat(otherTypes)});
      continue;
    }
    const possible = constructors(type);
    const present = new Set(state.matrix.map(row => row[0].tag));
    if (possible !== null && possible.every(tag => present.has(tag))) {
      for (const tag of possible) {
        const arguments_ = constructorArguments(type, tag);
        pending.push({matrix: specialize(state.matrix, tag, arguments_.length),
          vector: Array(arguments_.length).fill(wildcard).concat(tail), columnTypes: arguments_.concat(otherTypes)});
      }
    } else {
      pending.push({matrix: state.matrix.filter(row => row[0].tag === '_').map(row => row.slice(1)),
        vector: tail, columnTypes: otherTypes});
    }
  }
  return false;
}

function matchWarnings(expression, warnings) {
  const matrix = [];
  const columnTypes = [expression.matched.type];
  for (let index = 0; index < expression.arms.length; index++) {
    const arm = expression.arms[index];
    const pattern = patternTree(arm.pattern);
    if (index > 0 && !useful(matrix, [pattern], columnTypes)) {
      warnings.push({position: arm.pattern.position, priority: 2, message: 'this match case is unused'});
    }
    matrix.push([pattern]);
  }
  if (useful(matrix, [wildcard], columnTypes)) {
    warnings.push({position: expression.position, priority: 1, message: 'this match is not exhaustive'});
  }
}

function recursionClass(binding, group) {
  let references = 0;
  let allTail = true;
  function reference(expression, tail) {
    if (expression.target?.group !== group) return;
    references++;
    if (!tail) allTail = false;
  }
  function visit(expression, tail) {
    switch (expression.kind) {
      case 'name': reference(expression, false); break;
      case 'application': {
        const arguments_ = [];
        let head = expression;
        while (head.kind === 'application') { arguments_.push(head.argument); head = head.fn; }
        if (head.kind === 'name') reference(head, tail);
        else visit(head, false);
        for (let i = arguments_.length - 1; i >= 0; i--) visit(arguments_[i], false);
        break;
      }
      case 'fun': visit(expression.body, false); break;
      case 'unary': visit(expression.expression, false); break;
      case 'binary':
        visit(expression.left, false);
        visit(expression.right, tail && (expression.operator === '&&' || expression.operator === '||'));
        break;
      case 'if': visit(expression.condition, false); visit(expression.yes, tail); visit(expression.no, tail); break;
      case 'pair': visit(expression.first, false); visit(expression.second, false); break;
      case 'list': for (const element of expression.elements) visit(element, false); break;
      case 'match':
        visit(expression.matched, false);
        for (const arm of expression.arms) visit(arm.expression, tail);
        break;
      case 'let':
        for (const local of expression.group.bindings) visit(local.expression, false);
        visit(expression.body, tail);
        break;
    }
  }
  visit(leadingFunctions(binding.expression).body, true);
  return references === 0 ? null : allTail ? 'tail recursive' : 'recursive';
}

function staticChecks(item, environment) {
  const warnings = [];
  const binders = [];
  const groups = [];
  function binder(name, position, excluded, group = null) {
    const result = {name, position, excluded, group, used: 0};
    binders.push(result);
    return result;
  }
  function patternBindings(pattern, scope) {
    if (pattern.kind === 'name') scope.set(pattern.name, binder(pattern.name, pattern.position, false));
    else if (pattern.kind === 'pair' || pattern.kind === 'cons') {
      patternBindings(pattern.first, scope);
      patternBindings(pattern.second, scope);
    } else if (pattern.kind === 'list') for (const element of pattern.elements) patternBindings(element, scope);
  }
  function groupScope(group, scope, topLevel) {
    const extended = new Map(scope);
    const members = group.bindings.map(binding => binder(binding.name, binding.position, topLevel, group));
    group.bindings.forEach((binding, i) => extended.set(binding.name, members[i]));
    for (const binding of group.bindings) visit(binding.expression, group.recursive ? extended : scope);
    group.usedRec = members.some(member => member.used > 0);
    groups.push(group);
    return extended;
  }
  function visit(expression, scope) {
    switch (expression.kind) {
      case 'name':
        expression.target = scope.get(expression.name);
        expression.target.used++;
        break;
      case 'fun': {
        const extended = new Map(scope);
        const parameter = expression.parameter;
        if (parameter.name !== '_') extended.set(parameter.name, binder(parameter.name, parameter.position, false));
        visit(expression.body, extended);
        break;
      }
      case 'application': visit(expression.fn, scope); visit(expression.argument, scope); break;
      case 'binary': visit(expression.left, scope); visit(expression.right, scope); break;
      case 'unary': visit(expression.expression, scope); break;
      case 'if': visit(expression.condition, scope); visit(expression.yes, scope); visit(expression.no, scope); break;
      case 'pair': visit(expression.first, scope); visit(expression.second, scope); break;
      case 'list': for (const element of expression.elements) visit(element, scope); break;
      case 'let': visit(expression.body, groupScope(expression.group, scope, false)); break;
      case 'match':
        visit(expression.matched, scope);
        matchWarnings(expression, warnings);
        for (const arm of expression.arms) {
          const extended = new Map(scope);
          patternBindings(arm.pattern, extended);
          visit(arm.expression, extended);
        }
        break;
    }
  }
  const scope = new Map([...environment.keys()].map(name => [name, {name, used: 0, group: null}]));
  if (item.kind === 'declaration') groupScope(item.group, scope, true);
  else visit(item.expression, scope);
  for (const group of groups) {
    if (!group.recursive) continue;
    if (!group.usedRec) warnings.push({position: group.recPosition, priority: 3, message: 'unused rec flag'});
    for (const binding of group.bindings) binding.classification = recursionClass(binding, group);
  }
  for (const name of binders) {
    if (!name.excluded && !name.name.startsWith('_') && name.used === 0) {
      warnings.push({position: name.position, priority: 4, message: `unused variable '${name.name}'`});
    }
  }
  warnings.sort((first, second) => positionOrder(first.position, second.position) || first.priority - second.priority);
  return warnings;
}

function classification(binding) {
  return binding.classification ? ' (' + binding.classification + ')' : '';
}

function appendTypes(lines, item, inferencer) {
  if (item.kind === 'declaration') {
    for (const binding of item.group.bindings) lines.push(`${binding.name} : ${printType(binding.scheme.type)}${classification(binding)}`);
  } else lines.push('- : ' + printType(item.expression.type));
  inferencer.locals.sort((first, second) => positionOrder(first.position, second.position));
  for (const binding of inferencer.locals) {
    const {line, column} = binding.position;
    lines.push(`  ${binding.name} (${line}:${column}) : ${printType(binding.scheme.type, new Map(), binding.scheme.quantified)}${classification(binding)}`);
  }
}

function report(lines, sources, statistics, position, kind, message) {
  const key = {warning: 'warnings', 'syntax error': 'syntax', 'type error': 'type', 'runtime error': 'runtime'}[kind];
  statistics[key]++;
  lines.push(`${position.file}:${position.line}:${position.column}: ${kind}: ${message}`);
  const source = sources.get(position.file).lines;
  if (position.line <= source.length) {
    lines.push('    ' + source[position.line - 1]);
    lines.push(' '.repeat(position.column + 3) + '^');
  }
}

function syntaxMessage(token) {
  if (token.kind === 'invalid') return token.message;
  return token.kind === 'eof' ? 'unexpected end of file' : `unexpected '${token.text}'`;
}

function recover(parser) {
  while (parser.current().kind !== 'eof' && parser.current().text !== ';;') parser.index++;
  if (parser.current().text === ';;') parser.index++;
}

function main() {
  const fileNames = ['prelude.ml', 'program.ml'];
  const sources = new Map(fileNames.map(name => {
    const text = fs.readFileSync('input/' + name, 'ascii');
    return [name, {text, lines: text === '' ? [] : text.slice(0, -1).split('\n')}];
  }));
  const outputs = {'types.txt': [], 'values.txt': [], 'errors.txt': [], 'formatted.ml': []};
  const summaries = [];
  let {typeEnvironment, valueEnvironment} = initialEnvironments();
  for (const file of fileNames) {
    const statistics = {items: 0, bindings: 0, syntax: 0, type: 0, runtime: 0, warnings: 0, calls: 0};
    const emit = (position, kind, message) => report(outputs['errors.txt'], sources, statistics, position, kind, message);
    const parser = new Parser(tokenize(sources.get(file).text, file));
    const evaluator = new Evaluator();
    const pending = new Map();
    outputs['types.txt'].push(`== ${file} ==`);
    outputs['values.txt'].push(`== ${file} ==`);
    outputs['formatted.ml'].push(`(* ${file} *)`);
    while (parser.current().kind !== 'eof') {
      statistics.items++;
      let item;
      try { item = parser.item(); }
      catch (error) {
        if (!(error instanceof ParseError)) throw error;
        emit(error.token.position, 'syntax error', syntaxMessage(error.token));
        recover(parser);
        continue;
      }
      outputs['formatted.ml'].push(formatItem(item));
      if (item.kind === 'signature') {
        const old = pending.get(item.name);
        if (old !== undefined) emit(old.position, 'warning', `signature for '${item.name}' is never used`);
        pending.set(item.name, item);
        continue;
      }
      const signatures = item.kind === 'declaration' ? item.group.bindings.map(binding => {
        const signature = pending.get(binding.name) ?? null;
        pending.delete(binding.name);
        return signature;
      }) : [];
      const inferencer = new Inferencer();
      let newTypes;
      try {
        if (item.kind === 'declaration') {
          newTypes = inferencer.group(item.group, typeEnvironment, true);
          checkSignatures(item.group, signatures, newTypes);
        } else inferencer.expression(item.expression, typeEnvironment);
      } catch (error) {
        if (!(error instanceof InferenceError)) throw error;
        emit(error.position, 'type error', typeErrorMessage(error));
        continue;
      }
      const warnings = staticChecks(item, typeEnvironment);
      appendTypes(outputs['types.txt'], item, inferencer);
      for (const warning of warnings) emit(warning.position, 'warning', warning.message);
      try {
        if (item.kind === 'declaration') {
          const newValues = evaluator.group(item.group, valueEnvironment);
          for (const binding of item.group.bindings) outputs['values.txt'].push(`${binding.name} = ${printValue(newValues.get(binding.name))}`);
          typeEnvironment = newTypes;
          valueEnvironment = newValues;
          statistics.bindings += item.group.bindings.length;
        } else outputs['values.txt'].push('- = ' + printValue(evaluator.expression(item.expression, valueEnvironment)));
      } catch (error) {
        if (!(error instanceof RuntimeError)) throw error;
        emit(error.position, 'runtime error', error.message);
      }
    }
    const remaining = [...pending.values()].sort((first, second) => positionOrder(first.position, second.position));
    for (const signature of remaining) emit(signature.position, 'warning', `signature for '${signature.name}' is never used`);
    statistics.calls = evaluator.calls;
    summaries.push(`${file}: ` + Object.entries(statistics).map(([name, value]) => `${name}=${value}`).join(' '));
  }
  outputs['errors.txt'].push('== summary ==', ...summaries);
  fs.mkdirSync('output', {recursive: true});
  for (const [file, lines] of Object.entries(outputs)) fs.writeFileSync('output/' + file, lines.join('\n') + '\n', 'ascii');
}

main();

'use strict';

const operators = new Map([
  ['||', [1, true]], ['&&', [2, true]], ['=', [3, false]], ['<>', [3, false]],
  ['<', [3, false]], ['>', [3, false]], ['<=', [3, false]], ['>=', [3, false]],
  ['::', [4, true]], ['^', [4, true]], ['+', [5, false]], ['-', [5, false]],
  ['*', [6, false]], ['/', [6, false]], ['mod', [6, false]],
]);

class ParseError extends Error {
  constructor(token) { super('syntax error'); this.token = token; }
}

class Parser {
  constructor(tokens) { this.tokens = tokens; this.index = 0; }
  current() { return this.tokens[this.index]; }
  fail() { throw new ParseError(this.current()); }
  take(text) {
    if (this.current().text !== text) return null;
    return this.tokens[this.index++];
  }
  expect(text) {
    const token = this.take(text);
    if (token === null) this.fail();
    return token;
  }
  name(allowWildcard = false) {
    const token = this.current();
    if (token.kind !== 'name' || (!allowWildcard && token.text === '_')) this.fail();
    this.index++;
    return {name: token.text, position: token.position};
  }
  functions(parameters, body, position) {
    for (let i = parameters.length - 1; i >= 0; i--) body = {kind: 'fun', parameter: parameters[i], body, position};
    return body;
  }
  binding() {
    const binding = this.name();
    const parameters = [];
    while (this.current().kind === 'name') parameters.push(this.name(true));
    this.expect('=');
    binding.expression = this.functions(parameters, this.expression(), binding.position);
    return binding;
  }
  group() {
    const position = this.expect('let').position;
    const recursive = this.take('rec');
    const bindings = [this.binding()];
    while (this.take('and')) bindings.push(this.binding());
    return {bindings, recursive: recursive !== null, recPosition: recursive?.position, position};
  }
  item() {
    if (this.take('val')) {
      const name = this.name();
      this.expect(':');
      const type = this.typeExpression();
      this.expect(';;');
      return {kind: 'signature', ...name, type};
    }
    let item;
    if (this.current().text === 'let') {
      const group = this.group();
      if (this.take('in')) item = {kind: 'expression', expression: {kind: 'let', group, body: this.expression(), position: group.position}};
      else item = {kind: 'declaration', group};
    } else item = {kind: 'expression', expression: this.expression()};
    this.expect(';;');
    return item;
  }
  expression() {
    const token = this.current();
    if (token.text === 'let') {
      const group = this.group();
      this.expect('in');
      return {kind: 'let', group, body: this.expression(), position: token.position};
    }
    if (this.take('fun')) {
      const parameters = [this.name(true)];
      while (this.current().kind === 'name') parameters.push(this.name(true));
      this.expect('->');
      return this.functions(parameters, this.expression(), token.position);
    }
    if (this.take('if')) {
      const condition = this.expression();
      this.expect('then');
      const yes = this.expression();
      this.expect('else');
      return {kind: 'if', condition, yes, no: this.expression(), position: token.position};
    }
    if (this.take('match')) {
      const matched = this.expression();
      this.expect('with');
      this.take('|');
      const arms = [];
      do {
        const pattern = this.pattern();
        this.expect('->');
        arms.push({pattern, expression: this.expression()});
      } while (this.take('|'));
      return {kind: 'match', matched, arms, position: token.position};
    }
    return this.binary(1);
  }
  binary(minimum) {
    let left = this.unary();
    while (operators.has(this.current().text) && operators.get(this.current().text)[0] >= minimum) {
      const token = this.tokens[this.index++];
      const [precedence, rightAssociative] = operators.get(token.text);
      const right = this.binary(rightAssociative ? precedence : precedence + 1);
      left = {kind: 'binary', operator: token.text, operatorPosition: token.position, left, right, position: left.position};
    }
    return left;
  }
  atomicStart() {
    const token = this.current();
    return ['int', 'string'].includes(token.kind) || (token.kind === 'name' && token.text !== '_')
      || ['true', 'false', '(', '['].includes(token.text);
  }
  unary() {
    const minus = this.take('-');
    if (minus !== null) return {kind: 'unary', expression: this.unary(), position: minus.position, operatorPosition: minus.position};
    let expression = this.atomic();
    while (this.atomicStart()) expression = {kind: 'application', fn: expression, argument: this.atomic(), position: expression.position};
    return expression;
  }
  atomic() {
    const token = this.current();
    if (token.kind === 'int' || token.kind === 'string') {
      this.index++;
      return {kind: token.kind, value: token.value, position: token.position};
    }
    if (token.text === 'true' || token.text === 'false') {
      this.index++;
      return {kind: 'bool', value: token.text === 'true', position: token.position};
    }
    if (token.kind === 'name' && token.text !== '_') { this.index++; return {kind: 'name', name: token.text, position: token.position}; }
    if (this.take('(')) {
      const first = this.expression();
      if (this.take(',')) {
        const second = this.expression();
        this.expect(')');
        return {kind: 'pair', first, second, position: token.position};
      }
      this.expect(')');
      return first;
    }
    if (this.take('[')) {
      const elements = [];
      if (!this.take(']')) {
        elements.push(this.expression());
        while (this.take(';')) elements.push(this.expression());
        this.expect(']');
      }
      return {kind: 'list', elements, position: token.position};
    }
    this.fail();
  }
  pattern() {
    const first = this.atomicPattern();
    if (!this.take('::')) return first;
    return {kind: 'cons', first, second: this.pattern(), position: first.position};
  }
  atomicPattern() {
    const token = this.current();
    if (token.kind === 'name') {
      this.index++;
      return {kind: token.text === '_' ? 'wildcard' : 'name', name: token.text, position: token.position};
    }
    if (token.kind === 'int' || token.kind === 'string') {
      this.index++;
      return {kind: token.kind, value: token.value, position: token.position};
    }
    if (token.text === 'true' || token.text === 'false') {
      this.index++;
      return {kind: 'bool', value: token.text === 'true', position: token.position};
    }
    if (this.take('-')) {
      const integer = this.current();
      if (integer.kind !== 'int') this.fail();
      this.index++;
      return {kind: 'int', value: -integer.value, position: token.position};
    }
    if (this.take('(')) {
      const first = this.pattern();
      if (this.take(',')) {
        const second = this.pattern();
        this.expect(')');
        return {kind: 'pair', first, second, position: token.position};
      }
      this.expect(')');
      return first;
    }
    if (this.take('[')) {
      const elements = [];
      if (!this.take(']')) {
        elements.push(this.pattern());
        while (this.take(';')) elements.push(this.pattern());
        this.expect(']');
      }
      return {kind: 'list', elements, position: token.position};
    }
    this.fail();
  }
  typeExpression() {
    const first = this.productType();
    return this.take('->') ? {kind: 'function', args: [first, this.typeExpression()]} : first;
  }
  productType() {
    const first = this.listType();
    return this.take('*') ? {kind: 'pair', args: [first, this.listType()]} : first;
  }
  listType() {
    let type = this.typeAtom();
    while (this.take('list')) type = {kind: 'list', args: [type]};
    return type;
  }
  typeAtom() {
    const token = this.current();
    if (['int', 'bool', 'string'].includes(token.text)) { this.index++; return {kind: token.text, args: []}; }
    if (token.kind === 'typevar') { this.index++; return {kind: 'variable', name: token.text}; }
    if (this.take('(')) {
      const type = this.typeExpression();
      this.expect(')');
      return type;
    }
    this.fail();
  }
}

module.exports = {Parser, ParseError, operators};

'use strict';

let serial = 0;
const integer = {kind: 'int', args: []};
const boolean = {kind: 'bool', args: []};
const string = {kind: 'string', args: []};

function fresh() { return {kind: 'var', number: serial++, bound: null}; }
function list(element) { return {kind: 'list', args: [element]}; }
function pair(first, second) { return {kind: 'pair', args: [first, second]}; }
function fn(argument, result) { return {kind: 'function', args: [argument, result]}; }

function resolve(type) {
  if (type.kind !== 'var' || type.bound === null) return type;
  type.bound = resolve(type.bound);
  return type.bound;
}

function freeVariables(type, result = new Set()) {
  type = resolve(type);
  if (type.kind === 'var') result.add(type);
  else for (const argument of type.args) freeVariables(argument, result);
  return result;
}

function occurs(variable, type) {
  type = resolve(type);
  return type === variable || (type.kind !== 'var' && type.args.some(argument => occurs(variable, argument)));
}

function unify(expected, found) {
  function visit(first, second, component) {
    first = resolve(first);
    second = resolve(second);
    if (first === second) return null;
    if (first.kind === 'var') {
      if (occurs(first, second)) return {kind: 'occurs', variable: first, other: second, expected: first, found: second, component};
      first.bound = second;
      return null;
    }
    if (second.kind === 'var') {
      if (occurs(second, first)) return {kind: 'occurs', variable: second, other: first, expected: first, found: second, component};
      second.bound = first;
      return null;
    }
    if (first.kind !== second.kind) return {kind: 'mismatch', expected: first, found: second, component};
    for (let i = 0; i < first.args.length; i++) {
      const failure = visit(first.args[i], second.args[i], true);
      if (failure !== null) return failure;
    }
    return null;
  }
  return visit(expected, found, false);
}

function monomorphic(type) { return {type, quantified: new Set()}; }

function generalize(type, environment) {
  const free = new Set();
  for (const scheme of environment.values()) {
    for (const variable of freeVariables(scheme.type)) if (!scheme.quantified.has(variable)) free.add(variable);
  }
  const quantified = new Set([...freeVariables(type)].filter(variable => !free.has(variable)));
  return {type, quantified};
}

function instantiate(scheme) {
  const replacements = new Map();
  function copy(type) {
    type = resolve(type);
    if (type.kind === 'var') {
      if (!scheme.quantified.has(type)) return type;
      if (!replacements.has(type)) replacements.set(type, fresh());
      return replacements.get(type);
    }
    return {kind: type.kind, args: type.args.map(copy)};
  }
  return copy(scheme.type);
}

module.exports = {integer, boolean, string, fresh, list, pair, fn, resolve, freeVariables,
  occurs, unify, monomorphic, generalize, instantiate};
